    "accommodation.charges.pick_one_desc": "Select any booking on the left to view billed items, add an extra charge, or chase pending invoices.",
    "accommodation.charges.empty_title": "No charges on this booking yet",
    "accommodation.charges.empty_desc": "Add base rent for the stay or one-off extras (cleaning, damage, deposit). Amounts stay exact through to billing.",
    "accommodation.charges.status_col": "Status",
    "accommodation.charge.status.pending": "Pending",
